-- Resources -------------------------------------------------------
WITH seed(provider_external_id,external_id,name,description,resource_type,address,phone,email,website,availability_status,access_type,requires_referral,requires_id,gender_policy,population_focus,confidence_score,verification_notes) AS (
VALUES
('housing-provider-abe-brown','housing-abe-brown-insphire','Abe Brown Ministries — inspHire Transitional Housing','Transitional housing support for eligible inspHire participants rebuilding after incarceration or justice-system involvement. The 12-month program combines housing stability with professional development, employment assistance, coaching and transportation support.','transitional_housing','{"street":"2921 N 29th Street","city":"Tampa","state":"FL","zip":"33605"}'::jsonb,'813-247-3285','info@abebrown.org','https://abebrown.org/insphire-become-a-client/','unknown'::availability_status,'phone_intake'::resource_access_type,FALSE,TRUE,'gender_inclusive',ARRAY['reentry']::text[],98::smallint,'Housing is for enrolled inspHire participants. Official eligibility excludes sexual-offense convictions and generally excludes habitual violent offenders, with some circumstances reviewed individually.'),
('housing-provider-inner-strength','housing-inner-strength-reentry','Inner Strength Living — Reentry Housing','Shared, structured housing across Tampa Bay for people seeking a fresh start, including individuals re-entering society. Homes are furnished and drug- and alcohol-free.','shared_housing','{"city":"Tampa Bay","state":"FL"}'::jsonb,'813-296-6210','Help@innerstrengthliving.com','https://innerstrengthliving.com/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,TRUE,'gender_inclusive',ARRAY['reentry']::text[],95::smallint,'Official site explicitly offers a Re-entry Program. Exact residence is assigned after intake.'),
('housing-provider-70x7','housing-70x7-justice-involved','70x7 Housing Foundation — Justice-Involved Shared Housing','Drug- and alcohol-free shared housing in the Tampa Bay area for vulnerable adults, including justice-involved people and returning citizens.','shared_housing','{"city":"Tampa Bay","state":"FL"}'::jsonb,'813-727-7076','info@70x7housing.org','https://70x7housing.org/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],95::smallint,'Official site identifies justice-involved/returning citizens among populations served.'),
('housing-provider-timothy-initiative','housing-timothy-initiative-restoration','Timothy Initiative — Residential Restoration & Journey Homes','Year-long Christ-centered residential restoration for men rebuilding after addiction, incarceration, homelessness or other major life disruption. The pathway includes recovery homes, work therapy and transition toward independent living.','recovery_residence','{"street":"3309 N 15th Street","city":"Tampa","state":"FL","zip":"33605"}'::jsonb,'813-843-3645','info@TimothyInitiative.org','https://timothyinitiative.org/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,FALSE,'men_only',ARRAY['reentry']::text[],97::smallint,'Official current program explicitly includes men rebuilding after incarceration.'),
('housing-provider-project-180','housing-project-180-residential','Project 180 — Residential Program','Long-term residential reentry program in Sarasota for formerly incarcerated men in active recovery, including stable residency, food, clothing, transportation, employment assistance and other reentry support.','transitional_housing','{"city":"Sarasota","state":"FL"}'::jsonb,'941-780-5227','antonia@project180reentry.org','https://www.project180reentry.org/portfolio-item/residential-program/','unknown'::availability_status,'phone_intake'::resource_access_type,TRUE,FALSE,'men_only',ARRAY['reentry']::text[],98::smallint,'Official program offers up to two years of residency; candidates are interviewed and may be vetted by justice-system partners.'),
('housing-provider-angels-mercy','housing-angels-mercy-tarp','Angels of Mercy Ministries — Angels Restoration Place','Bridge and transitional housing for women reentering society after incarceration, homelessness, addiction or related displacement, with counseling, mentoring, recovery structure and employment support.','transitional_housing','{"city":"Sanford","state":"FL"}'::jsonb,'321-696-9850','auralynn@angelsofmercyministries.org','https://angelsofmercyministries.org/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,FALSE,'women_only',ARRAY['reentry']::text[],98::smallint,'2025 program material says participants are triaged regardless of criminal history, credit or past evictions.'),
('housing-provider-reign-hope','housing-reign-hope-reentry','Reign of Hope — Second Chance Reentry Housing','Shared and independent second-chance housing across Central Florida. Reentry Housing is designed for non-violent offenders rebuilding after incarceration.','shared_housing','{"state":"FL"}'::jsonb,'407-848-0617','contact@reignofhope.org','https://reignofhope.org/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],93::smallint,'Official site explicitly labels the program Second Chance Housing and Reentry Housing for non-violent offenders.'),
('housing-provider-open-homes','housing-open-homes-regeneration','Open Homes Fellowship — Regeneration Residential Program','Christian residential program for adult men addressing addiction and life-controlling issues. Open Homes has a pre-release intake path for applicants who are still incarcerated.','recovery_residence','{"street":"1831 Central Park Ave","city":"Orlando","state":"FL","zip":"32807"}'::jsonb,'407-382-7962','info@openhomesfellowship.com','https://openhomesfellowship.org/intake/','unknown'::availability_status,'phone_intake'::resource_access_type,FALSE,TRUE,'men_only',ARRAY['reentry']::text[],95::smallint,'Official intake page allows incarcerated applicants to be considered through coordination with a judicial representative.'),
('housing-provider-operation-new-hope','housing-operation-new-hope-orlando','Operation New Hope — Orlando Reentry Housing Support','Ready4Work Orlando support for justice-impacted people includes case management and transitional-housing assistance alongside employment, mental-health, transportation and stabilization services.','housing_navigation','{"street":"3815 E Colonial Drive","city":"Orlando","state":"FL","zip":"32803"}'::jsonb,'321-234-4782','info@operationnewhope.org','https://operationnewhope.org/ready4work-orlando/','unknown'::availability_status,'web_intake'::resource_access_type,FALSE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],95::smallint,'Classified as housing navigation/support rather than a promise of a bed at the office.'),
('housing-provider-lords-place','housing-lords-place-reentry-navigation','The Lord''s Place — Reentry Housing Navigation','Housing navigation and wraparound reentry support for eligible people convicted in and returning to Palm Beach County, including housing referrals, employment, treatment, identification and benefits assistance.','housing_navigation','{"street":"2808 N Australian Ave","city":"West Palm Beach","state":"FL","zip":"33407"}'::jsonb,'561-467-6874','VKlein@TheLordsPlace.org','https://thelordsplace.org/what-we-do/reentry-program/','unknown'::availability_status,'phone_intake'::resource_access_type,TRUE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],98::smallint,'Provider explicitly says its Reentry Program is not itself internal housing; this record represents housing navigation.'),
('housing-provider-riverside-house','housing-riverside-house-rrc','Riverside House — Residential Reentry Program','Structured residential reentry in Miami for men and women transitioning from incarceration, with supervised housing, meals, case management, employment preparation, counseling and transition planning.','transitional_housing','{"street":"968 NW 2nd Street","city":"Miami","state":"FL","zip":"33128"}'::jsonb,'305-326-9799','info@riverside-house.org','https://riversidehouse.org/programs/residential-reentry/','unknown'::availability_status,'phone_intake'::resource_access_type,TRUE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],99::smallint,'Residential placement is through BOP or other authorized federal supervision partners; not public walk-in rental housing.'),
('housing-provider-banyan','housing-banyan-rrc-miami','Banyan Community Health — Residential Reentry Center','Bureau of Prisons residential reentry center in Miami providing structured, supervised housing and access to health care, employment counseling, job placement and reintegration support for people nearing release.','transitional_housing','{"street":"120 NW 59th Street","city":"Miami","state":"FL","zip":"33127"}'::jsonb,'305-398-6127',NULL,'https://banyanhealth.org/behavioral-health/adult-psychiatric/behavioral-health-centers/','unknown'::availability_status,'phone_intake'::resource_access_type,TRUE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],99::smallint,'Correctional/federal referral placement; not open public rental housing.'),
('housing-provider-restoration-destination','housing-restoration-destination-reentry','Restoration Destination — Reentry Housing','Transitional and permanent shared housing in Pahokee for people rebuilding after incarceration, with transportation, probation/registration support, employment assistance and other reentry services.','shared_housing','{"street":"120 Pelican Lake Drive","city":"Pahokee","state":"FL","zip":"33476"}'::jsonb,'561-924-5556','info@restorationdestination.org','https://restorationdestination.org/prison-reentry-housing/','unknown'::availability_status,'phone_intake'::resource_access_type,FALSE,FALSE,'gender_inclusive',ARRAY['reentry']::text[],98::smallint,'Official site plus 211 Palm Beach/Treasure Coast record updated 2026-04-29 checked. 211 lists first-time non-violent offenders case-by-case and states the agency is compliant to house sex offenders.'),
('housing-provider-fern-house','housing-fern-house-reentry-recovery','Fern House — Residential Recovery & Transitional Living','Structured residential rehabilitation and transitional living for men affected by chronic alcohol/drug addiction, including formerly incarcerated and homeless men.','recovery_residence','{"street":"1958 Church Street","city":"West Palm Beach","state":"FL","zip":"33409"}'::jsonb,'561-471-0430','info@fernhouse.org','https://fernhouse.org/mission/','unknown'::availability_status,'phone_intake'::resource_access_type,FALSE,FALSE,'men_only',ARRAY['reentry']::text[],98::smallint,'Official page explicitly identifies formerly incarcerated men among the population served.')
)
INSERT INTO resources (
 provider_id,name,description,category,resource_type,address,phone,email,website,
 availability_status,verification_status,is_active,walk_ins_accepted,requires_id,
 requires_referral,access_type,is_map_ready,gender_policy,population_focus,
 external_id,source_file,import_batch_id,last_imported_at,last_verified_at,
 confidence_score,stale_after_days,verification_notes
)
SELECT p.id,s.name,s.description,'housing'::resource_category,s.resource_type,s.address,
 s.phone,s.email,s.website,s.availability_status,'verified'::verification_status,TRUE,FALSE,
 s.requires_id,s.requires_referral,s.access_type,FALSE,s.gender_policy,s.population_focus,
 s.external_id,'migration_061','housing_second_chance_061',now(),now(),s.confidence_score,30,s.verification_notes
FROM seed s JOIN providers p ON p.external_id=s.provider_external_id
ON CONFLICT (external_id) WHERE external_id IS NOT NULL DO UPDATE SET
 provider_id=EXCLUDED.provider_id,name=EXCLUDED.name,description=EXCLUDED.description,
 category=EXCLUDED.category,resource_type=EXCLUDED.resource_type,address=EXCLUDED.address,
 phone=EXCLUDED.phone,email=EXCLUDED.email,website=EXCLUDED.website,
 availability_status=EXCLUDED.availability_status,verification_status=EXCLUDED.verification_status,
 is_active=EXCLUDED.is_active,walk_ins_accepted=EXCLUDED.walk_ins_accepted,
 requires_id=EXCLUDED.requires_id,requires_referral=EXCLUDED.requires_referral,
 access_type=EXCLUDED.access_type,is_map_ready=EXCLUDED.is_map_ready,
 gender_policy=EXCLUDED.gender_policy,population_focus=EXCLUDED.population_focus,
 source_file=EXCLUDED.source_file,import_batch_id=EXCLUDED.import_batch_id,
 last_imported_at=EXCLUDED.last_imported_at,last_verified_at=EXCLUDED.last_verified_at,
 confidence_score=EXCLUDED.confidence_score,stale_after_days=EXCLUDED.stale_after_days,
 verification_notes=EXCLUDED.verification_notes,updated_at=now();

