('housing-project-180-residential',TRUE,NULL::boolean,FALSE,TRUE,NULL::boolean,NULL::integer,NULL::integer,730,'https://www.project180reentry.org/about-us/contact-us/','941-780-5227','Formerly incarcerated men in active recovery; up to two years. Provider states it does not knowingly admit people with a crime against a child, sex crime or arson history; other restrictions are reviewed during intake.'),
('housing-angels-mercy-tarp',TRUE,NULL::boolean,NULL::boolean,TRUE,NULL::boolean,NULL::integer,NULL::integer,548,'https://angelsofmercyministries.org/wp-content/uploads/2025/07/AOM-Brouchure-and-Application-Corrected-2025-V3.pdf','321-696-9850','Women reentering from prison, jail or rehab. 2025 material says triage regardless of criminal history, credit or past evictions. Applicants must be 30 days clean/sober. Program described as 6–18 months; $300 entrance fee and $175 weekly rent.'),
('housing-reign-hope-reentry',TRUE,FALSE,NULL::boolean,NULL::boolean,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://reignofhope.org/apply-housing','407-848-0617','Official program description says Reentry Housing is for non-violent offenders rebuilding after incarceration. Sex-offense eligibility is not separately stated.'),
('housing-open-homes-regeneration',NULL::boolean,NULL::boolean,NULL::boolean,TRUE,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://openhomesfellowship.org/intake/','407-382-7962','Adult men; drug/alcohol-free at least 72 hours before face-to-face interview and urine test. Incarcerated applicants can be evaluated with a judicial representative. Specific offense exclusions are not stated.'),
('housing-operation-new-hope-orlando',NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://operationnewhope.org/apply-for-our-program/','321-234-4782','Ready4Work serves justice-impacted people and lists transitional housing among Orlando support services. Housing navigation/support only; office is not represented as a residence.'),
('housing-lords-place-reentry-navigation',NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://thelordsplace.org/what-we-do/reentry-program/','561-467-6874','For people involved with the Palm Beach County justice system; includes housing navigation/referrals. Provider explicitly says Reentry is not an internal housing program.'),
('housing-riverside-house-rrc',NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,TRUE,NULL::integer,NULL::integer,NULL::integer,'https://riversidehouse.org/programs/residential-reentry/','305-326-9799','Placement through BOP/authorized federal supervision partners; no direct public residential application. Residents follow schedules and curfews. Co-ed with separated living areas.'),
('housing-banyan-rrc-miami',NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://banyanhealth.org/behavioral-health/adult-psychiatric/behavioral-health-centers/','305-398-6127','Residential Reentry Center operated with the Federal Bureau of Prisons for people nearing release. Placement is correctional/federal referral.'),
('housing-restoration-destination-reentry',TRUE,FALSE,TRUE,TRUE,NULL::boolean,90000,NULL::integer,NULL::integer,'https://restorationdestination.org/prison-reentry-housing/','561-924-5556','Direct reentry housing. Current 211 record lists first-time non-violent offenders case-by-case, $900/month plus $400 administrative fee, and states the agency is compliant with state/county guidelines to house sex offenders.'),
('housing-fern-house-reentry-recovery',NULL::boolean,NULL::boolean,NULL::boolean,TRUE,NULL::boolean,NULL::integer,NULL::integer,NULL::integer,'https://fernhouse.org/mission/','561-471-0430','Drug/alcohol-free residential recovery for men; provider explicitly serves formerly incarcerated men. Fern House II provides longer-term transitional living after the primary recovery program. Specific offense exclusions are not stated.')
)
INSERT INTO resource_housing_details (
 resource_id,accepts_felony,accepts_violent_offense,accepts_sex_offense,
 requires_sobriety,has_curfew,minimum_monthly_cost_cents,deposit_cents,max_stay_days,
 application_url,intake_phone,eligibility_notes,housing_details_last_checked_at
)
SELECT r.id,d.accepts_felony,d.accepts_violent_offense,d.accepts_sex_offense,
 d.requires_sobriety,d.has_curfew,d.minimum_monthly_cost_cents,d.deposit_cents,d.max_stay_days,
 d.application_url,d.intake_phone,d.eligibility_notes,now()
FROM d JOIN resources r ON r.external_id=d.external_id
ON CONFLICT (resource_id) DO UPDATE SET
 accepts_felony=EXCLUDED.accepts_felony,accepts_violent_offense=EXCLUDED.accepts_violent_offense,
 accepts_sex_offense=EXCLUDED.accepts_sex_offense,requires_sobriety=EXCLUDED.requires_sobriety,
 has_curfew=EXCLUDED.has_curfew,minimum_monthly_cost_cents=EXCLUDED.minimum_monthly_cost_cents,
 deposit_cents=EXCLUDED.deposit_cents,max_stay_days=EXCLUDED.max_stay_days,
 application_url=EXCLUDED.application_url,intake_phone=EXCLUDED.intake_phone,
 eligibility_notes=EXCLUDED.eligibility_notes,housing_details_last_checked_at=EXCLUDED.housing_details_last_checked_at,
 updated_at=now();

