INSERT INTO resource_evidence(resource_id,claim_field,method,outcome,source_url,source_name,checked_at,checked_by,notes)
SELECT r.id,ev.claim_field,ev.method,ev.outcome,ev.source_url,ev.source_name,now(),'StreetRise migration 061',ev.notes
FROM ev JOIN resources r ON r.external_id=ev.external_id
WHERE NOT EXISTS (
 SELECT 1 FROM resource_evidence e
 WHERE e.resource_id=r.id AND e.claim_field IS NOT DISTINCT FROM ev.claim_field
   AND e.source_url IS NOT DISTINCT FROM ev.source_url
);
